f:Description>\r\n                </prf:component>\r\n                <prf:component>\r\n                        <rdf:Description ID=\"WapCharacteristics\">\r\n				<rdf:type resource=\"http://www.w3.org/TR/PR-rdf-schema#WapCharacteristics\" />\r\n                                <prf:WapDeviceClass>C</prf:WapDeviceClass>\r\n                                <prf:WapPushMsgSize>685</prf:WapPushMsgSize>\r\n                                <prf:WapVersion>1.2.1/June 2000</prf:WapVersion>\r\n                                <prf:WmlVersion>\r\n                                        <rdf:Bag>\r\n                                                <rdf:li>1.2.1/June 2000</rdf:li>\r\n                                        </rdf:Bag>\r\n                                </prf:WmlVersion>\r\n                                <prf:WmlDeckSize>2800</prf:WmlDeckSize>\r\n                                <prf:WmlScriptVersion>\r\n                                        <rdf:Bag>\r\n                                                <rdf:li>1.2.1/June 2000</rdf:li>\r\n                                        </rdf:Bag>\r\n                                </prf:WmlScriptVersion>\r\n                                <prf:WmlScriptLibraries>\r\n                                        <rdf:Bag>\r\n                                                <rdf:li>Lang</rdf:li>\r\n                                                <rdf:li>Float</rdf:li>\r\n                                                <rdf:li>String</rdf:li>\r\n                                                <rdf:li>URL</rdf:li>\r\n                                                <rdf:li>WMLBrowser</rdf:li>\r\n                                                <rdf:li>Dialogs</rdf:li>\r\n                                        </rdf:Bag>\r\n                                </prf:WmlScriptLibraries>\r\n                                <prf:WtaiLibraries>\r\n                                        <rdf:Bag>\r\n                                                <rdf:li>WTA.Public.makeCall</rdf:li>\r\n                                                <rdf:li>WTA.Public.sendDTMF</rdf:li>\r\n                                                <rdf:li>WTA.Public.addPBEntry</rdf:li>\r\n                                        </rdf:Bag>\r\n                                </prf:WtaiLibraries>\r\n                        </rdf:Description>\r\n                </prf:component>\r\n        </rdf:Description>\r\n</RDF>\r\n');
