INSERT INTO `uaprof` (`id`, `uaprof_url`, `fetched`, `last_tried`, `last_return`, `uaprof_xml`) VALUES (841, 'http://uaprof.vtext.com/nokia/nokia6315i/nokia6315i.xml', 1, '2023-07-19 16:44:11', 200, '<?xml version=\"1.0\" encoding=\"UTF-8\" ?>\r\n<!--\r\n***********************************************************************\r\n*	Verizon Wireless 3G Handset UA Prof\r\n*	\r\n* 	Version:		T03_0\r\n*	Created:		01/27/06\r\n*       Modified:               03/25/06\r\n*	Author:		        NOKIA\r\n*	Organization:	        NOKIA\r\n* 	\r\n* 	Copyright 2003-2006 NOKIA\r\n* 	\r\n*	Note\r\n*\r\n*\r\n*	Revision History\r\n*		 \r\n************************************************************************\r\n-->	 \r\n\r\n<rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\" xmlns:prf=\"http://www.wapforum.org/profiles/UAPROF/ccppschema-20010430#\" xmlns=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\">\r\n\r\n<rdf:Description rdf:ID=\"VerizonWirelessProfile\">\r\n\r\n<!--********************** Hardware Platform Description ********************-->\r\n<prf:component>\r\n	<rdf:Description rdf:ID=\"HardwarePlatform\">\r\n		<rdf:type rdf:resource=\"http://www.wapforum.org/profiles/UAPROF/ccppschema-20010430#HardwarePlatform\"/>\r\n\r\n<!-- ******** Vendor/model *******-->	\r\n<!-- Enter the vendor name here.  This must match the vendor name in the EDF -->\r\n		<prf:Vendor>\r\n			NOKIA\r\n		</prf:Vendor>\r\n	\r\n<!-- Enter the device model name here.  This must match the SKU -->		\r\n		<prf:Model>\r\n			Nokia 6315i\r\n		</prf:Model>\r\n		\r\n<!-- Change if different -->\r\n		<prf:CPU>\r\n			ARM9\r\n		</prf:CPU>\r\n		\r\n		\r\n<!--****** Display ******-->\r\n		\r\n<!-- Enter screen size in pixels here - width x height -->\r\n		<prf:ScreenSize>\r\n			176x220\r\n		</prf:ScreenSize>\r\n		\r\n<!-- \"Yes\" if device supports color -->	\r\n		<prf:ColorCapable>\r\n			Yes\r\n		</prf:ColorCapable>\r\n		\r\n<!-- Enter the color or grayscale depth here -->\r\n		<prf:BitsPerPixel>\r\n			18\r\n		</prf:BitsPerPixel>\r\n		\r\n<!-- Change if not 1:1 -->\r\n		<prf:PixelAspectRatio>\r\n			1x1\r\n		</prf:PixelAspectRatio>\r\n		\r\n<!-- This should always be \"Yes\" -->\r\n		<prf:ImageCapable>\r\n			Yes\r\n		</prf:ImageCapable>\r\n\r\n<!-- Enter the screen size in characters here.  Use the default font. -->\r\n		<prf:ScreenSizeChar>\r\n			14x14\r\n		</prf:ScreenSizeChar>\r\n\r\n<!--Change to \"No\" only if the default font on the device is not proportional-->\r\n		<prf:StandardFontProportional>\r\n			No\r\n		</prf:StandardFontProportional>\r\n\r\n\r\n<!-- List the supported output character sets here. UTF-8 and UTF-16 are required by spec-->\r\n		<prf:OutputCharSet>\r\n			<rdf:Bag>\r\n				<rdf:li>ISO-8859-1</rdf:li>\r\n				<rdf:li>US-ASCII</rdf:li>\r\n			</rdf:Bag>\r\n		</prf:OutputCharSet>\r\n		\r\n		\r\n\r\n<!-- ******** Input capabilities ******-->		\r\n<!-- List the supported Input character sets here -->\r\n		<prf:InputCharSet>\r\n			<rdf:Bag>\r\n				<rdf:li>ISO-8859-1</rdf:li>\r\n			</rdf:Bag>\r\n		</prf:InputCharSet>\r\n		\r\n<!-- This should always be \"Yes\" -->\r\n		<prf:TextInputCapable>\r\n			Yes\r\n		</prf:TextInputCapable>\r\n		\r\n<!-- This value should only be changed if the device does not use a standard DTMF keypad -->\r\n		<prf:Keyboard>\r\n			PhoneKeypad\r\n		</prf:Keyboard>\r\n\r\n<!-- Enter the number of softkeys supported by the device -->\r\n		<prf:NumberOfSoftKeys>\r\n			2\r\n		</prf:NumberOfSoftKeys>\r\n		\r\n\r\n<!-- ********* Audio **********-->	\r\n\r\n<!-- This should always be \"Yes\" -->\r\n		<prf:SoundOutputCapable>\r\n			Yes\r\n		</prf:SoundOutputCapable>\r\n\r\n\r\n<!-- This should be \"Yes\" for all voice capable devices -->		\r\n		<prf:VoiceInputCapable>\r\n			Yes\r\n		</prf:VoiceInputCapable>\r\n\r\n<!--******************************-->		\r\n	</rdf:Description>\r\n</prf:component>\r\n\r\n\r\n\r\n<!--********************** Software Platform Description *******************-->\r\n<prf:component>\r\n	<rdf:Description rdf:ID=\"SoftwarePlatform\">\r\n	<rdf:type rdf:resource=\"http://www.wapforum.org/profiles/UAPROF/ccppschema-20010430#SoftwarePlatform\"/>\r\n\r\n<!-- ***** Basic ******-->\r\n\r\n<!-- Should be \"Yes\" for all Java capable devices -->\r\n	<prf:AcceptDownloadableSoftware>\r\n			No\r\n	</prf:AcceptDownloadableSoftware>\r\n	\r\n<!-- Use this for J2ME app support -->	 \r\n	\r\n<!-- Enter the software version number here.  This must match the version reported via IOTA-->\r\n	<prf:SoftwareNumber>\r\n		T03_0\r\n	</prf:SoftwareNumber>\r\n\r\n<!-- Should not change if using Qualcomm software-->	\r\n	<prf:OSName>\r\n		Rex\r\n	</prf:OSName>\r\n\r\n<!-- Should not change if using Qualcomm software-->	\r\n	<prf:OSVendor>\r\n		QUALCOMM\r\n	</prf:OSVendor>\r\n	\r\n<!-- Fill in version of DMSS Software base -->\r\n	<prf:OSVersion>\r\n		DMSS6500\r\n	</prf:OSVersion>\r\n\r\n<!-- ********* CCPP accept **********-->\r\n\r\n<!-- List all accepted MIME types here -->\r\n	<prf:CcppAccept>\r\n		<rdf:Bag>\r\n			<!-- Markup languages -->\r\n			<rdf:li>text/html</rdf:li>\r\n			<rdf:li>text/plain</rdf:li>\r\n			<rdf:li>text/vnd.wap.wml</rdf:li>\r\n			<rdf:li>application/vnd.wap.wmlc</rdf:li>\r\n			<rdf:li>application/xhtml+xml</rdf:li>\r\n			<rdf:li>application/vnd.wap.xhtml+xml</rdf:li>\r\n\r\n			<rdf:li>application/vnd.phonecom.mmc-xml</rdf:li>\r\n			<rdf:li>application/vnd.wap.wmlscriptc</rdf:li>\r\n			<rdf:li>multipart/mixed</rdf:li>\r\n			<rdf:li>multipart/related</rdf:li>\r\n			\r\n			<!-- Images -->\r\n			<rdf:li>image/vnd.wap.wbmp</rdf:li>\r\n			<rdf:li>image/jpeg</rdf:li>\r\n			<rdf:li>image/png</rdf:li>\r\n			<rdf:li>image/gif</rdf:li>\r\n			<rdf:li>image/bmp</rdf:li>\r\n			<rdf:li>image/x-up-wpng</rdf:li>\r\n	\r\n			<!-- Audio / Multimedia  -->\r\n			<rdf:li>audio/midi</rdf:li>\r\n			<rdf:li>audio/x-midi</rdf:li>\r\n			<rdf:li>audio/vnd.qcelp</rdf:li>\r\n			<rdf:li>audio/qcp</rdf:li>\r\n		</rdf:Bag>\r\n\r\n	</prf:CcppAccept>\r\n	\r\n<!-- List all accepted character sets here. UTF-8 and UTF-16 required by spec-->\r\n	\r\n	<prf:CcppAccept-Charset>\r\n		<rdf:Bag>\r\n			<rdf:li>ISO-8859-1</rdf:li>\r\n			<rdf:li>US-ASCII</rdf:li>\r\n			<!-- Enter other items... -->\r\n		</rdf:Bag>\r\n	\r\n	</prf:CcppAccept-Charset>\r\n	\r\n<!-- List all accepted languages here in order of preference -->\r\n	\r\n	<prf:CcppAccept-Language>\r\n		<rdf:Bag>\r\n			<rdf:li>en</rdf:li>\r\n			<rdf:li>es</rdf:li>\r\n			<!-- Enter other languages, e.g. spanish, french... -->\r\n		</rdf:Bag>\r\n	</prf:CcppAccept-Language>\r\n	\r\n<!-- List all accepted transfer encodings here -->\r\n	\r\n	<prf:CcppAccept-Encoding>\r\n		<rdf:Bag>\r\n                        <rdf:li>deflate</rdf:li> \r\n                        <rdf:li>gzip</rdf:li> \r\n			<!-- Enter items... -->\r\n		</rdf:Bag>\r\n	</prf:CcppAccept-Encoding>\r\n	\r\n<!-- ******** Input Encoders ******-->\r\n<!-- Don\'t know if we need this or not... -->\r\n	<prf:AudioInputEncoder>\r\n	\r\n	</prf:AudioInputEncoder>\r\n	\r\n<!--******************************-->	\r\n	</rdf:Description>\r\n</prf:component>\r\n\r\n<!--********************** Network Characteristics Description **************-->\r\n	<prf:component>\r\n	<rdf:Description rdf:ID=\"NetworkCharacteristics\">\r\n	<rdf:type rdf:resource=\"http://www.wapforum.org/profiles/UAPROF/ccppschema-20010430#NetworkCharacteristics\"/>\r\n	\r\n<!-- Indicate support for SSL 3.0 and TLS 1.0 -->\r\n	<prf:SecuritySupport>\r\n		<rdf:Bag>\r\n			<rdf:li>SSL-3.0</rdf:li>\r\n			<rdf:li>TLS-1.0</rdf:li>\r\n		</rdf:Bag>\r\n	</prf:SecuritySupport>\r\n	\r\n<!-- Indicate support for IS-2000 release 0 packet data bearer -->\r\n<!-- May add more detail here in a later rev. - eg. IPv6 -->\r\n	<prf:SupportedBearers>\r\n		<rdf:Bag>\r\n			<rdf:li>IPv4</rdf:li>\r\n                       		<rdf:li>SMS</rdf:li>\r\n		</rdf:Bag>\r\n	</prf:SupportedBearers>\r\n		\r\n	</rdf:Description>\r\n</prf:component>\r\n\r\n<!--********************** Browser UA Description ***************************-->\r\n\r\n<prf:component>\r\n	<rdf:Description rdf:ID=\"BrowserUA\">\r\n	<rdf:type rdf:resource=\"http://www.wapforum.org/profiles/UAPROF/ccppschema-20010430#BrowserUA\"/>\r\n	\r\n<!-- ********* Browser Identification ********** -->\r\n<!-- Enter the browser vendor/product name here -->\r\n	<prf:BrowserName>\r\n		OPENWAVE\r\n	</prf:BrowserName>\r\n	\r\n<!-- Enter the browser version here -->\r\n	<prf:BrowserVersion>\r\n		6.2.3.2\r\n	</prf:BrowserVersion>\r\n	\r\n<!-- ********** Capabilities *********** -->\r\n<!-- Frames supported?? -->\r\n	<prf:FramesCapable>\r\n		No\r\n	</prf:FramesCapable>\r\n	\r\n<!-- Basic tables are supported in xhtml-basic -->\r\n	<prf:TablesCapable>\r\n		Yes\r\n	</prf:TablesCapable>\r\n	\r\n<!-- Frames supported?? -->\r\n	<prf:PreferenceForFrames>\r\n		No\r\n	</prf:PreferenceForFrames>\r\n	\r\n<!-- *********** Applets/Servlets  ********** -->	\r\n	<prf:DownloadableBrowserApps>\r\n		<rdf:Bag>\r\n		</rdf:Bag>\r\n	</prf:DownloadableBrowserApps>\r\n	\r\n	<prf:JavaAppletEnabled>\r\n		No\r\n	</prf:JavaAppletEnabled>\r\n	\r\n	<prf:JavaScriptEnabled>\r\n		No\r\n	</prf:JavaScriptEnabled>\r\n	\r\n	\r\n<!-- ************* XHTML support - indicate XHTML-Basic 1.0 ************ -->\r\n	<prf:XhtmlVersion>\r\n		XHTML-Basic/1.0\r\n	</prf:XhtmlVersion>\r\n	\r\n<!-- May need to add additional modules here -->\r\n	<prf:XhtmlModules>\r\n		<!-- Enter values here -->\r\n	</prf:XhtmlModules>\r\n\r\n<!--******************************-->\r\n	</rdf:Description>\r\n</prf:component>\r\n\r\n\r\n \r\n<!--********************** WAP Characteristics Description ******************-->\r\n\r\n<prf:component>\r\n	<rdf:Description rdf:ID=\"WapCharacteristics\">\r\n	<rdf:type rdf:resource=\"http://www.wapforum.org/profiles/UAPROF/ccppschema-20010430#WapCharacteristics\"/>\r\n\r\n\r\n \r\n<!--******** General ***********-->\r\n\r\n	<prf:WapVersion>\r\n		2.0\r\n	</prf:WapVersion>\r\n\r\n<!--*********** WML ************-->\r\n\r\n<!-- If full wml 2.0 is supported, it should be added here -->	\r\n	<prf:WmlVersion>\r\n		<rdf:Bag>\r\n			<rdf:li>1.1</rdf:li>\r\n			<rdf:li>1.2</rdf:li>\r\n		</rdf:Bag>\r\n	</prf:WmlVersion>\r\n\r\n<!-- Enter the maximum deck size for wml -->\r\n	<prf:WmlDeckSize>\r\n		65535\r\n	</prf:WmlDeckSize>\r\n\r\n<!--******************************-->\r\n	</rdf:Description>\r\n</prf:component>\r\n\r\n<!--*************** Push Characteristics Description ********************-->\r\n\r\n<prf:component>\r\n	<rdf:Description rdf:ID=\"PushCharacteristics\">\r\n	<rdf:type rdf:resource=\"http://www.wapforum.org/profiles/UAPROF/ccppschema-20010430#PushCharacteristics\"/>\r\n\r\n	<prf:Push-Accept>\r\n		<rdf:Bag>\r\n                      <rdf:li>text/plain</rdf:li> \r\n                      <rdf:li>text/vnd.wap.si</rdf:li> \r\n                      <rdf:li>text/vnd.wap.sl</rdf:li> \r\n                      <rdf:li>text/vnd.wap.co</rdf:li> \r\n                      <rdf:li>text/vnd.wap.wml</rdf:li> \r\n                      <rdf:li>application/vnd.wap.wmlc</rdf:li> \r\n                      <rdf:li>application/vnd.wap.xhtml+xml</rdf:li>\r\n                      <rdf:li>application/vnd.wap.sic</rdf:li> \r\n                      <rdf:li>application/vnd.wap.slc</rdf:li> \r\n                      <rdf:li>application/vnd.wap.coc</rdf:li>  \r\n		</rdf:Bag>\r\n	</prf:Push-Accept>\r\n\r\n	<prf:Push-Accept-Charset>\r\n		<rdf:Bag>\r\n			<rdf:li>ISO-8859-1</rdf:li>\r\n			<rdf:li>UTF-8</rdf:li>\r\n		</rdf:Bag>\r\n	</prf:Push-Accept-Charset>\r\n\r\n	<prf:Push-Accept-Encoding>\r\n		<rdf:Bag>\r\n		</rdf:Bag>\r\n	</prf:Push-Accept-Encoding>\r\n\r\n	<prf:Push-Accept-AppID>\r\n		<rdf:Bag>\r\n			<rdf:li>x-wap-application:wml.ua</rdf:li>\r\n		</rdf:Bag>\r\n	</prf:Push-Accept-AppID>\r\n\r\n	<prf:Push-MsgSize>\r\n		1600\r\n	</prf:Push-MsgSize>\r\n\r\n<!-- ********************************-->\r\n	</rdf:Description>\r\n</prf:component>\r\n\r\n</rdf:Description>\r\n</rdf:RDF>');
